/** A fake %LOCALAPPDATA% holding one extracted Construct repo whose markers say the VM
 *  was provisioned with an OLDER Construct than the one installed on this PC. */
function makeConstructInstall(): string {
  const localAppData = NodeFS.mkdtempSync(NodePath.join(NodeOS.tmpdir(), "t3-construct-updates-"));
  const scriptsDir = NodePath.join(
    localAppData,
    "The-Construct",
    "permissionBRICK-The-Construct-main",
    "The-Construct-main",
  );
  NodeFS.mkdirSync(scriptsDir, { recursive: true });
  NodeFS.writeFileSync(NodePath.join(scriptsDir, "Auto-Install.ps1"), "# marker\n");
  NodeFS.writeFileSync(NodePath.join(scriptsDir, "Update-T3Code.ps1"), "# reprovision\n");
  NodeFS.writeFileSync(
    NodePath.join(scriptsDir, ".construct-settings.json"),
    "\uFEFF" +
      JSON.stringify({
        installedCommit: "dc44958114c7c43145c8f7830f6185235a1d752b",
        provisionedCommit: "b262652aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa",
      }),
  );
  return localAppData;
}

describe("DesktopUpdates (Construct builds)", () => {
  it.effect("seeds the Construct facts from the local markers at configure time", () =>
    Effect.gen(function* () {
      const localAppData = makeConstructInstall();
      const harness = makeHarness({
        appVersion: "0.0.38-construct.bb8cb346",
        env: { LOCALAPPDATA: localAppData },
      });
      yield* Effect.gen(function* () {
        const updates = yield* DesktopUpdates.DesktopUpdates;
        yield* Effect.scoped(updates.configure);
        const state = yield* updates.getState;
        assert.isTrue(state.enabled);
        assert.equal(state.status, "available");
        assert.equal(state.channel, "latest");
        assert.isDefined(state.construct);
        assert.equal(state.construct?.installedCommit, "dc44958114c7c43145c8f7830f6185235a1d752b");
        assert.isTrue(state.construct?.provisionStale);
        assert.equal(state.construct?.action, "reprovision");
        assert.equal(state.construct?.vmName, "agent-vm");
        // electron-updater never ran an update check.
        assert.equal(harness.checkCount(), 0);
        // The channel preference cannot be changed on a Construct build.
        const afterChannel = yield* updates.setChannel("nightly");
        assert.equal(afterChannel.channel, "latest");
      }).pipe(Effect.provide(harness.layer));
      NodeFS.rmSync(localAppData, { recursive: true, force: true });
    }),
  );

  it.effect("keeps the facts but launches nothing while auto-updates are disabled", () =>
    Effect.gen(function* () {
      const localAppData = makeConstructInstall();
      const harness = makeHarness({
        appVersion: "0.0.38-construct.bb8cb346",
        env: { LOCALAPPDATA: localAppData, T3CODE_DISABLE_AUTO_UPDATE: "true" },
      });
      yield* Effect.gen(function* () {
        const updates = yield* DesktopUpdates.DesktopUpdates;
        yield* Effect.scoped(updates.configure);
        const state = yield* updates.getState;
        assert.isFalse(state.enabled);
        assert.equal(state.status, "disabled");
        assert.isTrue(state.construct?.provisionStale);
        assert.equal(state.construct?.action, "reprovision");
        assert.isTrue(Option.isSome(yield* updates.disabledReason));
        const check = yield* updates.check("web-ui");
        assert.isFalse(check.checked);
        const download = yield* updates.download;
        assert.isFalse(download.completed);
        assert.equal(download.state.status, "disabled");
        assert.include(download.state.message ?? "", "T3CODE_DISABLE_AUTO_UPDATE");
        assert.isNull(download.state.construct?.runningAction ?? null);
      }).pipe(Effect.provide(harness.layer));
      NodeFS.rmSync(localAppData, { recursive: true, force: true });
    }),
  );
});

